import { notFound } from "next/navigation";
import { FounderRepositories } from "../../../../../../data/repositories/founderRepositories";
import { classifyPeptideExecutionState,createPeptideSupportHydrationModel,PeptideExecutionState } from "../../../../../../domain/services/PeptideExecutionManagementService";
import { PeptideExecutionDetailScreen } from "../../../../../../screens/PeptideExecutionScreen";
import PeptideSupportEditorScreen from "../../../../../../screens/PeptideSupportEditorScreen";
import { savePeptideExecution } from "./actions";
import { getLocalDateKey,resolveLocalTimeZone } from "../../../../../../domain/utils/localDate";
export const dynamic="force-dynamic";
export default async function Page({params,searchParams}){const{protocolId}=await params;const query=await searchParams;const user=await FounderRepositories.users.getCurrentUser();const[protocol,items,reminders]=await Promise.all([FounderRepositories.protocols.getProtocolById(protocolId),FounderRepositories.executionItems.listExecutionItems(user.id),FounderRepositories.reminders.listReminders(user.id)]);if(!protocol||protocol.userId!==user.id||protocol.category!=="peptide"||protocol.status!=="active")notFound();const classification=classifyPeptideExecutionState({protocol,executionItems:items});if(classification.state===PeptideExecutionState.INVALID)notFound();const item=classification.record;const timezone=resolveLocalTimeZone(user.timeZone??user.timezone);const localDate=getLocalDateKey(new Date(),timezone);if(query?.edit==="1"){const reminder=reminders.find((entry)=>entry.type==="protocol_reminder"&&entry.linkedEntityId===protocol.id)??null;return <PeptideSupportEditorScreen action={savePeptideExecution.bind(null,{protocolId,expectedRevision:item?.executionRevision??(item?1:null),supportEditor:"peptide_support_v1"})} hydration={createPeptideSupportHydrationModel({executionItem:item,protocol,reminder})} protocol={protocol}/>;}return <PeptideExecutionDetailScreen item={item} protocol={protocol} localDate={localDate} supportTerminology/>;}
